<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TecnoStore</title><link rel="stylesheet" href="assets/style.css"></head><body><aside><div class="brand">🛒 TecnoStore</div><div class="user">👤 <?=htmlspecialchars($_SESSION['usuario_nombre'])?><span><?=ucfirst(htmlspecialchars($_SESSION['usuario_rol']))?></span></div><nav><a class="active" href="index.php?controller=producto&action=listar">📦 Productos</a><a href="index.php?controller=producto&action=crear">➕ Nuevo producto</a><a href="#">📊 Dashboard</a></nav><a class="logout" href="index.php?controller=login&action=logout">🚪 Cerrar sesión</a></aside><main><header><div><h1>Productos</h1><p>Administra tu catálogo tecnológico</p></div><a class="btn" href="index.php?controller=producto&action=crear">+ Agregar producto</a></header><section class="stats"><div><b><?= $productos->num_rows ?></b><span>Productos</span></div><div><b>💻</b><span>Tecnología</span></div><div><b>S/</b><span>Precios en soles</span></div></section><div class="grid"><?php while($p=$productos->fetch_assoc()): ?><article class="card"><div class="pic"><?=htmlspecialchars($p['imagen'])?></div><div class="content"><span class="tag"><?=htmlspecialchars($p['categoria'])?></span><h2><?=htmlspecialchars($p['nombre'])?></h2><p><?=htmlspecialchars($p['descripcion'])?></p><strong>S/ <?=number_format($p['precio'],2)?></strong><div class="stock">Stock: <?=intval($p['stock'])?></div><div class="status <?=((int)$p['publicado']===1?'published':'draft')?>"><?=((int)$p['publicado']===1?'🟢 Publicado en catálogo':'⚪ Solo administración')?></div><div class="actions"><a href="index.php?controller=producto&action=editar&id=<?=$p['id']?>">✏️ Editar</a><a href="index.php?controller=producto&action=publicar&id=<?=$p['id']?>&estado=<?=((int)$p['publicado']===1?0:1)?>"><?=((int)$p['publicado']===1?'🚫 Ocultar del catálogo':'📢 Publicar en catálogo')?></a><a class="danger" onclick="return confirm('¿Eliminar producto?')" href="index.php?controller=producto&action=eliminar&id=<?=$p['id']?>">🗑️ Eliminar</a></div></div></article><?php endwhile; ?></div></main></body></html>
